selector_to_html = {"a[href=\"#a-worked-example\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">A worked example<a class=\"headerlink\" href=\"#a-worked-example\" title=\"Link to this heading\">\u00b6</a></h2><p>The RL10A-3-3A validation case in <code class=\"docutils literal notranslate\"><span class=\"pre\">validation/RL10/</span></code> is a hydrogen/oxygen\nupper-stage engine with <span class=\"math notranslate nohighlight\">\\(\\varepsilon = 61\\)</span>, <span class=\"math notranslate nohighlight\">\\(p_c = 33.2\\)</span> bar, and\n<span class=\"math notranslate nohighlight\">\\(c^* = 2375\\ \\mathrm{m\\,s^{-1}}\\)</span>, constructed with <code class=\"docutils literal notranslate\"><span class=\"pre\">p_amb=1e5</span></code>:</p>", "a[href=\"#specific-impulse-and-thrust-coefficient\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Specific Impulse and Thrust Coefficient<a class=\"headerlink\" href=\"#specific-impulse-and-thrust-coefficient\" title=\"Link to this heading\">\u00b6</a></h1><p>An <code class=\"docutils literal notranslate\"><span class=\"pre\">Aerothermodynamics</span></code> design point reports specific impulse under four\ndifferent names: <code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_vac</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_optimum</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_amb</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_SL</span></code>. They can\ndiffer by more than an order of magnitude for the same engine. This page\nexplains what each one assumes, and when the ambient values stop being\nmeaningful.</p>", "a[href=\"#from-ideal-to-delivered-performance\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">From ideal to delivered performance<a class=\"headerlink\" href=\"#from-ideal-to-delivered-performance\" title=\"Link to this heading\">\u00b6</a></h2><p>All four values are ideal: they come from a one-dimensional equilibrium\nexpansion and assume complete combustion. Real engines lose performance to\ntwo-dimensional divergence, the wall boundary layer, finite-rate chemistry, and\nimperfect injection.</p>", "a[href=\"#when-the-ambient-values-stop-being-valid\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">When the ambient values stop being valid<a class=\"headerlink\" href=\"#when-the-ambient-values-stop-being-valid\" title=\"Link to this heading\">\u00b6</a></h2><p>The expression for <span class=\"math notranslate nohighlight\">\\(C_{F,amb}\\)</span> assumes the nozzle flows full, with the exhaust\nattached to the wall all the way to the exit plane. A nozzle sized for vacuum\nviolates that assumption at sea level.</p><p>In the example above the exit pressure is 3.85 kPa against an ambient of\n101 kPa, an overexpansion of a factor of 26. Real flow does not tolerate this.\nThe exhaust separates from the wall well upstream of the exit, at roughly the\nstation where the wall pressure falls to <span class=\"math notranslate nohighlight\">\\(0.3\\)</span>\u2013<span class=\"math notranslate nohighlight\">\\(0.4\\)</span> times ambient, which for\nthis gas is somewhere near <span class=\"math notranslate nohighlight\">\\(\\varepsilon = 10\\)</span> rather than 61. The engine then\nbehaves like a much smaller nozzle, delivers substantially more than the\ntabulated 18.8 s, and generates severe lateral loads on the nozzle extension.</p>", "a[href=\"#the-four-quantities\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The four quantities<a class=\"headerlink\" href=\"#the-four-quantities\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_vac</span></code> is the vacuum specific impulse, <span class=\"math notranslate nohighlight\">\\(p_{amb} = 0\\)</span>. The full pressure\nterm is added, so this is the largest of the four. It is the value to use for\nupper stages and in-space engines, and it is what the mixture-ratio optimiser\nin <a class=\"reference internal\" href=\"../howto/mixture-ratio-optimisation.html\"><span class=\"doc\">Mixture ratio optimisation</span></a>\nmaximises.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Isp_optimum</span></code> is the specific impulse at <em>optimum expansion</em>, meaning the\ncondition <span class=\"math notranslate nohighlight\">\\(p_e = p_{amb}\\)</span> where the nozzle exit pressure exactly matches the\nsurrounding atmosphere. The pressure term vanishes and only <span class=\"math notranslate nohighlight\">\\(\\dot{m}v_e\\)</span>\nremains, so this quantity is simply <span class=\"math notranslate nohighlight\">\\(v_e/g_0\\)</span>. It is the number NASA CEA\nreports as <code class=\"docutils literal notranslate\"><span class=\"pre\">Isp</span></code>.</p>", "a[href=\"#if-you-are-interested-in-reading-more\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">If you are interested in reading more<a class=\"headerlink\" href=\"#if-you-are-interested-in-reading-more\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../howto/mixture-ratio-optimisation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Optimise mixture ratio<a class=\"headerlink\" href=\"#optimise-mixture-ratio\" title=\"Link to this heading\">\u00b6</a></h1><p>This how-to finds the oxidizer-to-fuel mixture ratio that gives the highest vacuum specific impulse for a fixed engine design point.</p><p>The example uses:</p>", "a[href=\"#where-the-differences-come-from\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Where the differences come from<a class=\"headerlink\" href=\"#where-the-differences-come-from\" title=\"Link to this heading\">\u00b6</a></h2><p>The thrust of a rocket nozzle has two parts:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
